"""Request IDs are generated by the service and shared with error responses."""

from uuid import UUID

import pytest
from fastapi.testclient import TestClient

from event_platform.main import create_app

pytestmark = pytest.mark.unit


def test_request_id_header_is_generated_for_each_request() -> None:
    with TestClient(create_app()) as client:
        first = client.get("/health/live")
        second = client.get("/health/live")

    first_id = first.headers["x-request-id"]
    second_id = second.headers["x-request-id"]
    UUID(first_id)
    UUID(second_id)
    assert first_id != second_id


def test_inbound_request_id_is_not_trusted() -> None:
    with TestClient(create_app()) as client:
        response = client.get("/missing", headers={"X-Request-ID": "attacker-controlled"})

    generated = response.headers["x-request-id"]
    UUID(generated)
    assert generated != "attacker-controlled"
    assert response.json()["request_id"] == generated


def test_successful_responses_include_server_request_id() -> None:
    with TestClient(create_app()) as client:
        live = client.get("/health/live")
        openapi = client.get("/openapi.json")

    live_id = live.headers["x-request-id"]
    openapi_id = openapi.headers["x-request-id"]
    UUID(live_id)
    UUID(openapi_id)
    assert live.status_code == 200
    assert openapi.status_code == 200
    assert live_id != openapi_id
